"""Original elbow clinical content and schematic SVGs; no patient imagery generated."""
from pathlib import Path
import json,textwrap,html
A=Path(__file__).resolve().parents[1]/'app/src/main/assets'
B='#556779';C='#73d9c3';T='#f5c276';D='#ff8b81';W='#c6d7e9'
def path(d,c=B,w=28):return f'<path d="{d}" fill="none" stroke="{c}" stroke-width="{w}" stroke-linecap="round" stroke-linejoin="round"/>'
def txt(x,y,s,c=W,size=15):
 width=max(12,int((576-x)/(size*.59)))
 lines=textwrap.wrap(s,width=width,break_long_words=False,break_on_hyphens=False)or['']
 return f'<text x="{x}" y="{y}" fill="{c}" font-size="{size}">'+''.join(f'<tspan x="{x}" dy="{0 if i==0 else size*1.2}">{html.escape(t)}</tspan>'for i,t in enumerate(lines))+'</text>'

def line(x,y,xx,yy,s):return f'<path d="M{x} {y}L{xx} {yy}" stroke="{W}" fill="none"/>'+txt(x,y-5,s)
def lesion(x,y,w=16,h=11):return f'<ellipse cx="{x}" cy="{y}" rx="{w}" ry="{h}" fill="{D}"/>'
def fluid(x,y,rx=25,ry=16):return f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{ry}" fill="#70b9ed" fill-opacity=".45" stroke="#70b9ed" stroke-width="2"/>'
def bone(d):return path(d,B,48)
def svg(title,plane,body):return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 500" role="img" aria-label="'+title+'"><rect width="600" height="500" rx="20" fill="#101d2a"/>'+txt(24,32,title,'#edf5ff',20)+txt(24,58,plane,'#94aabe',13)+body+txt(24,475,'Кость · хрящ · сухожилия/связки · дефект',W,13)+'</svg>'
def cor():
 return bone('M225 100L225 175Q270 220 320 175L320 100')+bone('M243 265L245 425')+bone('M355 273L365 425')+path('M200 208Q264 251 330 208',C,10)+path('M324 254Q356 234 384 254',C,9)+path('M174 182Q182 250 220 285',T,10)+path('M350 183Q374 220 385 249',T,9)+path('M155 181Q117 223 108 330',T,14)+path('M368 181Q420 228 429 330',T,14)+txt(32,115,'Медиально',W,13)+txt(430,115,'Латерально',W,13)
def sag():
 return bone('M295 100L295 190')+bone('M365 216Q324 244 328 295L340 424')+bone('M225 279L218 422')+path('M270 218Q300 254 330 220',C,10)+path('M202 251Q225 241 249 253',C,9)+txt(24,106,'Спереди',W,13)+txt(440,106,'Сзади',W,13)
def biceps(mode):
 body=sag()
 if mode=='full':body+=path('M143 119Q140 166 153 194',T,17)+path('M211 316L215 338',T,14)+fluid(178,254,27,41)+line(30,216,153,194,'Проксимальный конец')+line(28,367,212,338,'Бугристость лучевой')
 else:
  body+=path('M143 119Q143 228 211 326',T,18)
  if mode=='tend':body+=path('M187 278L210 325',T,25)+path('M188 280L207 316',D,5)
  if mode=='partial':body+=path('M195 303L210 325',D,9)+line(30,365,206,316,'Дефект части волокон')
  if mode=='bursa':body+=fluid(197,292,36,28)+path('M189 283L211 326',T,14)+line(25,367,171,301,'Двуглаволучевая сумка')
 return body+line(28,148,143,160,'Дистальный бицепс')
def triceps(mode):
 body=sag()
 if mode=='full':body+=path('M402 115L401 171',T,18)+fluid(390,200,26,25)+lesion(369,223)+line(434,285,388,196,'Все слои')
 else:body+=path('M390 116L383 223',T,9)+path('M408 116L404 181',T,12)+fluid(402,204,14,18)+line(422,291,382,213,'Глубокий слой цел')
 return body+line(430,149,405,153,'Трицепс')+line(27,353,364,223,'Локтевой отросток')
def lat():
 return bone('M275 100L275 180')+bone('M190 215Q165 260 210 285L220 420')+bone('M321 282L332 421')+path('M266 210Q295 237 323 218',C,10)+path('M296 257Q320 244 344 259',C,9)+path('M299 181Q298 240 255 282L232 326',T,10)+path('M308 183L338 257',T,9)+path('M293 272Q321 287 348 270',T,8)+txt(24,102,'Сзади',W,13)+txt(452,102,'Спереди',W,13)
F={}
F['normal']=svg('Ориентиры локтя','Условная корональная проекция',cor()+line(30,390,122,270,'Общее сухожилие сгибателей')+line(330,390,421,270,'Общее сухожилие разгибателей'))
F['lateral']=svg('Тендинопатия разгибателей','Латеральное начало · корональная проекция',cor()+path('M375 192Q401 221 414 252',T,23)+path('M377 195L402 229',D,5)+line(363,376,399,224,'Утолщение, волокна сохранены'))
F['lateral-partial']=svg('Частичный разрыв разгибателей','Латеральное начало · глубокая поверхность',cor()+lesion(376,197,10,16)+line(351,378,376,201,'Жидкостный дефект части волокон'))
F['medial']=svg('Тендинопатия сгибателей','Медиальное начало · корональная проекция',cor()+path('M154 183Q135 210 127 239',T,24)+path('M150 192L132 225',D,5)+line(30,378,138,209,'Отдельно проверить UCL'))
for k,t in [('tend','Тендинопатия бицепса'),('partial','Частичный разрыв бицепса'),('full','Полный разрыв бицепса'),('bursa','Двуглаволучевой бурсит')]:F['biceps-'+k]=svg(t,'Сагиттальная проекция · ход к лучевой кости',biceps(k))
for k,t in [('partial','Частичный разрыв трицепса'),('full','Полный разрыв трицепса')]:F['triceps-'+k]=svg(t,'Сагиттальная проекция · задняя поверхность',triceps(k))
F['ucl-partial']=svg('Частичный разрыв UCL','Передний пучок · медиальная сторона',cor()+path('M200 259L217 282','#70b9ed',7)+line(27,377,211,276,'Дефект глубокой поверхности'))
# Full UCL discontinuity: erase the complete width of the original band, show a fluid gap.
F['ucl-full']=svg('Полный разрыв UCL','Передний пучок · медиальная сторона',cor()+path('M184 229L201 260','#101d2a',18)+fluid(192,245,16,20)+line(26,376,192,245,'Перерыв всех волокон пучка'))
F['lcl']=svg('Латеральный связочный комплекс','Латеральная проекция · LUCL / RCL / кольцевая',lat()+lesion(299,197,12,15)+line(29,377,244,304,'LUCL → гребень супинатора')+line(368,340,333,242,'RCL → кольцевая'))
F['olecranon']=svg('Бурсит локтевого отростка','Сагиттальная проекция · поверхностно к трицепсу',sag()+path('M394 117L381 221',T,15)+fluid(430,217,26,38)+line(422,335,435,238,'Сумка вне сустава'))
F['valgus']=svg('Вальгусная перегрузка','Заднемедиальная зона · схема сочетания',cor()+lesion(192,247,11,16)+lesion(225,256,12,8)+line(30,379,209,251,'UCL + заднемедиальный отдел')+txt(40,420,'Компрессия латерально · тракция медиально',W,15))
F['dislocation']=svg('После вывиха: искать сочетание','Корональная проекция · условные зоны',cor()+lesion(355,187,12,12)+lesion(178,218,10,13)+lesion(344,255,11,9)+lesion(238,251,10,9)+line(28,380,238,251,'Венечный отросток')+line(350,410,344,255,'Головка лучевой кости'))
def p(label,fig,signs,key,trap):return dict(label=label,figure=fig,signs=signs,key=key,trap=trap)
def ul(*items):return '<ul>'+''.join('<li>'+s+'</li>'for s in items)+'</ul>'
def card(t,s):return '<article class="card"><h2>'+t+'</h2>'+s+'</article>'
def table(head,rows):return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+x+'</th>'for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td data-label="'+head[i]+'">'+x+'</td>'for i,x in enumerate(row))+'</tr>'for row in rows)+'</tbody></table></div>'
patterns=[
p('Ориентиры','normal','Четыре зоны: латеральная, медиальная, передняя и задняя. Проследить каждое сухожилие и связочный пучок от начала до прикрепления.','Сухожилие разгибателей лежит поверхностнее латеральных связок; общее сухожилие сгибателей — поверхностнее UCL.','Не переносить термин «МКС» из колена без уточнения: здесь медиальная локтевая коллатеральная связка UCL.'),
p('Латеральная тендинопатия','lateral','Утолщение и неоднородный внутрисухожильный сигнал в общем начале разгибателей, особенно короткого лучевого разгибателя кисти (ECRB). Непрерывные волокна прослеживаются.','Описать протяжённость, энтезис и наличие жидкостного дефекта; отдельно оценить RCL и LUCL. [Qi2013]','«Эпикондилит» — клинический термин; МР-признаки тендинопатии не доказывают, что это единственная причина боли.'),
p('Разрыв разгибателей','lateral-partial','Фокальный жидкостный дефект и нарушение части волокон общего сухожилия разгибателей; оценить глубокую поверхность у латерального надмыщелка.','Размеры вдоль сухожилия и поперёк, доля толщины ориентировочно, сохранный мостик и сопутствующее связочное повреждение.','Повышенного сигнала без дефекта и нарушения волокон недостаточно для уверенного разрыва. Не выводить PLRI из одного изменения сухожилия.'),
p('Медиальная тендинопатия','medial','Утолщение и изменённый сигнал общего начала сгибателей-пронаторов у медиального надмыщелка. Жидкостная щель с нарушением волокон указывает на разрыв.','Указать отдельно сухожилие, передний пучок UCL и локтевой нерв; это три разные структуры.','При боли медиально не ограничиваться сухожилием: возможны связочная патология, апофизарное повреждение у подростка или невропатия.'),
p('Бицепс: тендинопатия','biceps-tend','Утолщение и внутрисухожильный сигнал дистального бицепса при сохранённой непрерывности до бугристости лучевой кости.','Проследить длинноголовый и короткоголовый компоненты; оценить двуглаволучевую сумку. [Schenkels2020]','Косой ход и magic angle на коротком TE могут имитировать патологию: подтвердить на жидкостно-чувствительной серии с более длинным TE и в другой плоскости.'),
p('Бицепс: частичный разрыв','biceps-partial','Жидкостный дефект части волокон / одного компонента у прикрепления к бугристости лучевой кости при сохранении других волокон.','Описать компонент, длину, примерную долю прикрепления и качество видимости; FABS может помочь оценке. [Schenkels2020; Schmidt2025]','МРТ может недооценить частичный разрыв; точный процент и решение об операции не следует автоматически выводить из изображения.'),
p('Бицепс: полный разрыв','biceps-full','Полная потеря непрерывности сухожилия до прикрепления, жидкость в ложе, возможная проксимальная ретракция. Проверить оба компонента и lacertus fibrosus.','Измерить расстояние от дистального конца культи до ожидаемого прикрепления, указать положение локтя и доступность всей культи.','Сохранный lacertus fibrosus может ограничивать ретракцию: малое смещение не исключает полный разрыв. УЗИ полезно при расхождении с клиникой.'),
p('Трицепс: частичный разрыв','triceps-partial','Нарушение части волокон у локтевого отростка. Возможен полный отрыв поверхностного слоя при сохранении глубокого компонента. [Vicentini2022; Kholinne2018]','Указать поверхностный и глубокий слои раздельно, латеральное апоневротическое расширение, размеры дефекта и ретракцию повреждённого слоя.','Сохранность глубокого слоя не позволяет назвать разрыв всего сухожилия полным; оценка только одного сагиттального среза завышает тяжесть.'),
p('Трицепс: полный разрыв','triceps-full','Перерыв всех визуализируемых слоёв с жидкостным промежутком ± ретракцией; возможен костный отрыв от локтевого отростка.','Проверить всё прикрепление по ширине на аксиальных и сагиттальных срезах; указать костный фрагмент и его смещение.','Сравнить с рентгенографией при подозрении на маленький отрывной фрагмент; отёк или бурсит сами по себе не означают полный разрыв.'),
p('UCL: частичное повреждение','ucl-partial','Передний пучок может быть утолщён и неоднороден; частичный разрыв предполагает фокальный дефект с нарушением части волокон при сохранении остальных.','Указать проксимальное, среднее или дистальное расположение; оценить глубокую суставную поверхность. cMRI или dMRA по вопросу и качеству исследования. [SSR2023]','T-sign — распространение жидкости/контраста под дистальное прикрепление — требует сопутствующих признаков: вариабельное прикрепление может имитировать дефект.'),
p('UCL: полный разрыв','ucl-full','Полный перерыв конкретного пучка или его отрыв с жидкостным промежутком ± волнистостью и отёком; возможен костный компонент.','Передний пучок: медиальный надмыщелок → sublime tubercle венечного отростка локтевой кости. Уточнить, какой пучок повреждён.','Полный разрыв переднего пучка не означает разрыв всех трёх пучков UCL. Степень вальгусной нестабильности оценивают клинически / динамически.'),
p('Латеральные связки / PLRI','lcl','Оценить RCL, LUCL и кольцевую связку отдельно: начало, непрерывность, отёк, рубцовые изменения и отрыв.','LUCL идёт к гребню супинатора локтевой кости; RCL вплетается в кольцевую связку. При подозрении на PLRI SSR рекомендует обычную МРТ.','Непрерывный LUCL не всегда виден на одном срезе. Статическая МРТ выявляет морфологию, но не доказывает или исключает динамическую PLRI.'),
p('Локтевой бурсит','olecranon','Жидкость и утолщение стенок сумки поверхностно к локтевому отростку / дистальному трицепсу, иногда перегородки и окружающий отёк.','Указать размер, содержимое, состояние стенок, соседней клетчатки, сухожилия и кости.','По одному МР-сигналу нельзя надёжно разделить асептический, кристаллический и инфекционный бурсит; нужны клиника и при показаниях анализ аспирата.'),
p('Двуглаволучевой бурсит','biceps-bursa','Жидкость в сумке вокруг дистального бицепса у бугристости лучевой кости; проверить сухожилие и прилежащие нервные структуры.','Отличить жидкостную сумку от внутрисухожильного дефекта и от солидного образования.','Бурсит может сопровождать тендинопатию или разрыв, но сам по себе не доказывает ни то ни другое.'),
p('Вальгусная перегрузка','valgus','Искать сочетание медиальной тракционной патологии UCL / сгибателей, латеральных хондральных изменений и заднемедиального импинджмента.','В заднемедиальном отделе: остеофиты, синовит, хрящ, отёк кости и стрессовая линия локтевого отростка.','Отдельный остеофит не доказывает симптомный импинджмент; у подростка учитывать незавершённый рост, апофиз и остеохондральные поражения.'),
p('После вывиха','dislocation','Системно проверить головку лучевой кости, венечный отросток, суставную конгруэнтность, капсулу, медиальный и латеральный комплексы.','«Ужасная триада»: вывих локтя + перелом головки лучевой кости + перелом венечного отростка. Маленькие фрагменты важны для оценки стабильности.','Не ограничиваться найденным связочным разрывом; костную морфологию при необходимости уточняют КТ. Сохранённое положение после вправления не исключает повреждения стабилизаторов.')]
classifications=card('Анатомическая карта',table(['Зона','Структуры и прикрепления','Где смотреть'],[
('Медиально','UCL: передний, задний, поперечный пучки; общее сухожилие сгибателей-пронаторов. Передний пучок идёт к sublime tubercle локтевой кости.','Корональные ± косые; аксиальные для нерва и заднего пучка.'),
('Латерально','RCL → кольцевая связка; LUCL → гребень супинатора локтевой кости; кольцевая связка охватывает головку лучевой кости.','Корональные для начала; аксиальные / последовательные срезы для хода LUCL и кольцевой.'),
('Спереди','Бицепс → бугристость лучевой; плечевая мышца → локтевая кость; lacertus fibrosus → фасция предплечья.','Аксиальные + сагиттальные / косые; при вопросе к бицепсу — дополнительная FABS.'),
('Сзади','Трицепс → локтевой отросток: поверхностный и глубокий компоненты; латеральное расширение. Локтевая сумка лежит поверхностно.','Сагиттальные + аксиальные для всех слоёв и ширины прикрепления.')]))+card('Степень: описательная морфология',table(['Вариант','Основание','Как сформулировать'],[
('Тендинопатия','Утолщение / изменённый сигнал, без убедительного дефекта.','Тендинопатия ___; непрерывность волокон сохранена.'),('Частичный разрыв','Дефект части волокон с сохранным мостиком.','Локализация, компонент, размеры; ориентировочная доля толщины / footprint при достаточном разрешении.'),('Полный разрыв','Перерыв всех волокон указанного сухожилия или пучка.','Указать, разорван весь комплекс или один компонент, ретракцию и костный отрыв.'),('I–III для связок','Встречается градация: растяжение / частичный / полный разрыв.','Предпочтительно описать прямые признаки. Морфологическая степень не равна клинической степени нестабильности.')]))+card('Что измерять',ul('Дефект сухожилия: продольный × поперечный размеры и глубина, сохранный компонент. Процент — приблизительно, с указанием толщины или площади прикрепления в знаменателе.','Ретракция: от конца культи до ожидаемого прикрепления, в мм, по ходу сухожилия; указать положение локтя. Если культя вне поля — не занижать величину.','Связка: пучок, уровень и протяжённость повреждения, отрывной фрагмент; рутинного универсального МР-порога суставной щели для диагноза динамической нестабильности здесь нет.','Не переносить Ellman / Patte с вращательной манжеты и Palmer с TFCC на локоть. Порог 50% не является автоматической рекомендацией операции.'))
protocol=card('Базовый МР-протокол',ul('Три плоскости, специализированная катушка и малое поле обзора при полном охвате. Локоть по возможности в центре магнита, положение выбирают по переносимости.','Охват: от уровня выше надмыщелков до всего прикрепления бицепса к бугристости лучевой кости; при ретракции — расширить проксимально.','Корональные срезы ориентировать по надмыщелковой оси на аксиальных; аксиальные — поперёк локтя, сагиттальные — ортогонально.','Как минимум T1 без жироподавления и жидкостно-чувствительные серии с FS / STIR; PD / intermediate FS полезны для сухожилий и связок.','Рабочая цель тонких срезов — около 2–3 мм, если позволяют SNR и время. ACR2025 для аккредитации: аксиальные ≤4 мм, корональные dark-fluid ≤3 мм; это технические критерии, а не отдельный диагностический порог.','Внутривенный контраст обычно не нужен для обычной тендинопатии / разрыва; его необходимость определяется другим вопросом — инфекцией, синовитом, объёмным процессом.'))+card('FABS и прямая МР-артрография',ul('FABS: сгибание локтя, отведение плеча, супинация предплечья; дополнительная серия вдоль дистального бицепса, а не замена базового исследования. Не выполнять через выраженную боль.','Schenkels2020: убедительного выигрыша чувствительности / специфичности для частичных разрывов не получено, но оценка степени и согласие наблюдателей могут улучшаться. Поэтому FABS не гарантирует исключение разрыва.','SSR2023: при вальгусной нестабильности / UCL возможны обычная МРТ или dMRA; при PLRI рекомендована обычная МРТ. dMRA обсуждается при неопределённой МР-картине и значимом клиническом вопросе.','Прямая артрография — внутрисуставное введение; она не равна внутривенному контрастированию. Для сухожилий не назначается автоматически.'))+card('Ловушки и завершение просмотра',ul('Magic angle: сигнал на коротком TE сверить с сериями с более длинным TE, морфологией и другой плоскостью. Не объявлять разрыв по одному яркому участку.','T-sign: отличать истинное подрывание UCL с дефектом волокон от варианта прикрепления / суставного кармана; миллиметровый порог сам по себе недостаточен.','Спортсмен: утолщение и адаптивный сигнал связок могут быть бессимптомными; сопоставить с анамнезом и болевой зоной.','При отрицательной или неоднозначной МРТ и сохраняющейся слабости / подозрении на нестабильность указать ограничение; прицельное динамическое УЗИ и осмотр решают другой диагностический вопрос.','Просмотреть суставной хрящ, головочку плечевой кости, свободные тела, лучевую головку, венечный и локтевой отростки. OCD и болезнь Паннера у ребёнка не подменять «эпикондилитом».','Нервы: локтевой в кубитальном канале, срединный спереди, лучевой и глубокая ветвь в зоне супинатора. Развёрнутые критерии — в модуле туннельных невропатий.'))
templates=[
('Латеральная тендинопатия','Общее начало разгибателей у латерального надмыщелка ___, с ___ внутрисухожильным сигналом на ___. Убедительного жидкостного дефекта и перерыва волокон ___. RCL / LUCL ___. Заключение: МР-признаки тендинопатии общего сухожилия разгибателей ___.'),
('Частичный разрыв разгибателей / сгибателей','В общем начале ___ на ___ поверхности определяется жидкостный дефект ___×___ мм, глубиной примерно ___ локальной толщины; сохранные волокна ___. Прилежащие связки ___. Заключение: частичный разрыв общего сухожилия ___ у ___ надмыщелка.'),
('Частичный разрыв бицепса','У бугристости лучевой кости дефект ___ компонента дистального бицепса ___×___ мм, с сохранением ___ волокон. Оценка доли повреждения ___. Lacertus fibrosus ___, двуглаволучевая сумка ___. Заключение: МР-признаки частичного разрыва дистального бицепса ___.'),
('Полный разрыв бицепса','Непрерывность обоих компонентов дистального сухожилия бицепса до бугристости лучевой кости нарушена. Дистальный конец культи на ___ мм проксимальнее прикрепления при положении локтя ___. Lacertus fibrosus ___. Культя охвачена ___. Заключение: полный разрыв дистального сухожилия бицепса с ретракцией ___.'),
('Слои трицепса','У прикрепления к локтевому отростку повреждён ___ слой дистального трицепса, дефект ___×___ мм; ретракция повреждённого компонента ___ мм. Другой слой ___, латеральное расширение ___. Костный отрыв ___. Заключение: ___ разрыв дистального трицепса с вовлечением ___.'),
('Коллатеральная связка','В ___ отделе ___ пучка ___ связки определяется ___ с ___ сохранных волокон. Протяжённость ___ мм; костный компонент ___. Остальные стабилизаторы ___. Заключение: МР-признаки ___ повреждения ___; функциональную стабильность оценивают клинически / динамически.'),
('Бурсит','В ___ сумке скопление жидкости ___×___×___ мм; содержимое ___, стенки ___, окружающие ткани ___. Прилежащие сухожилие и кость ___. Заключение: МР-признаки ___ бурсита. Этиология по данной МР-картине достоверно не определяется.')]
